    text_a: "1- \u0641\u0631\u0627\u06CC\u0646\u062F \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0631\u0627 \u0628\u06CC\u0634\u062A\u0631 \u0639\u06CC\u0646\u06CC \u06A9\u0646\u06CC\u062F. 2- \u0647\u0646\u06AF\u0627\u0645 \u06A9\u0627\u0631 \u0628\u0627 \u0645\u0633\u0627\u06CC\u0644 \u0631\u06CC\u0627\u0636\u06CC \u06A9\u0647 \u0628\u0627 \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u062F\u0631\u06AF\u06CC\u0631 \u0647\u0633\u062A\u0646\u062F\u060C \u0631\u0627\u0647\u0646\u0645\u0627\u06CC\u06CC \u0647\u0627\u06CC\u06CC \u062F\u0631 \u0628\u06CC\u0631\u0648\u0646 \u0633\u0627\u0632\u06CC \u0641\u0631\u0627\u06CC\u0646\u062F \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0641\u0631\u0627\u0647\u0645 \u0646\u0645\u0627\u06CC\u06CC\u062F.  3- \u0628\u0627 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u0645\u062B\u0627\u0644 \u0627\u0632 \u0646\u062D\u0648\u0647 \u06A9\u0627\u0631\u0628\u0631\u062F \u06CC\u06A9 \u0642\u0627\u0639\u062F\u0647 \u062F\u0631 \u0645\u0648\u0642\u0639\u06CC\u062A \u0647\u0627\u06CC \u0645\u062E\u062A\u0644\u0641 \u0641\u0631\u0627\u06CC\u0646\u062F \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0627\u0633\u062A\u0642\u0631\u0627\u06CC\u06CC \u0631\u0627 \u0627\u062C\u0631\u0627 \u0646\u0645\u0627\u06CC\u06CC\u062F",
