    intro: "\u0627\u0641\u062A \u06A9\u0627\u0631\u0627\u06CC\u06CC \u0628\u0627 \u0646\u06CC\u0645\u200C\u0631\u062E\u0650 \u0628\u06CC\u200C\u0627\u0644\u06AF\u0648 \u06A9\u0646\u0627\u0631 \u0647\u0645 \u0622\u0645\u062F\u0647 \u2014 \u0627\u06CC\u0646 \u0641\u0642\u0637 \u06CC\u06A9 \u0646\u0634\u0627\u0646\u0647\u0654 \u0647\u0634\u062F\u0627\u0631 \u0627\u0633\u062A\u060C \u0646\u0647 \u0628\u06CC\u0634\u062A\u0631. \u0628\u06AF\u0630\u0627\u0631\u06CC\u062F \u0627\u0632 \u0627\u0631\u062A\u0628\u0627\u0637 \u0648 \u0631\u0641\u062A\u0627\u0631 \u0648\u0627\u0642\u0639\u06CC \u06A9\u0648\u062F\u06A9 \u0628\u067E\u0631\u0633\u0645 \u062A\u0627 \u0628\u0628\u06CC\u0646\u06CC\u0645 \u0627\u06CC\u0646 \u0646\u0634\u0627\u0646\u0647 \u0632\u0645\u06CC\u0646\u0647 \u062F\u0627\u0631\u062F \u06CC\u0627 \u0646\u0647.",
